param(
 [Parameter(Mandatory=$true)][string]$OutputDirectory,
 [string[]]$Cases=@('normal','water_1','water_2','water_3','water_64','water_100','upload','readback','truncate','identity','unknown_state','fatal','counter','tick_counter','revision_counter','bad_cfl'),
 [string]$ProbeScript='res://tests/integration/unified_edit_gpu_probe.gd',
 [string]$Engine='D:/game/steam/steamapps/common/Godot Engine/godot.windows.opt.tools.64.exe'
)
$ErrorActionPreference='Stop'
$projectDirectory=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$ownedProcesses=@(Get-CimInstance Win32_Process | Where-Object {$_.Name -like 'godot*' -and $_.CommandLine -like '*--script*' -and $_.CommandLine -like '*unified_edit*probe.gd*' -and $_.CommandLine -notlike '*--headless*'})
if($ownedProcesses.Count -gt 0){throw 'An owned GPU probe is already live'}
if($ProbeScript -notin @('res://tests/integration/unified_edit_gpu_probe.gd','res://tests/integration/unified_edit_target_probe.gd','res://tests/integration/unified_edit_suspended_probe.gd','res://tests/integration/unified_edit_water_probe.gd','res://tests/integration/unified_edit_height_probe.gd','res://tests/integration/unified_edit_views_probe.gd','res://tests/integration/unified_edit_half_gpu_probe.gd','res://tests/integration/unified_edit_initialization_probe.gd','res://tests/integration/unified_edit_restore_probe.gd','res://tests/integration/unified_edit_early_lifecycle_probe.gd','res://tests/integration/unified_edit_checkpoint_probe.gd','res://tests/integration/unified_edit_handoff_probe.gd','res://tests/integration/unified_edit_visuals_probe.gd','res://tests/integration/unified_edit_boundary_probe.gd')){throw 'Unknown GPU probe'}
if(Test-Path -LiteralPath $OutputDirectory){throw 'Fresh output required'}
New-Item -ItemType Directory -Path $OutputDirectory | Out-Null
$OutputDirectory=(Resolve-Path -LiteralPath $OutputDirectory).Path
$sources=@{}
foreach($directory in @('scripts/simulation/unified_edit','assets/unified_edit','scripts/simulation/edit_validation/frame_pipeline','scripts/sand/brushes','scripts/simulation/brushes','assets/brushes')){
 Get-ChildItem -LiteralPath (Join-Path $projectDirectory $directory) -File |
 Where-Object {$_.Extension -in @('.gd','.glsl','.glslinc','.tres','.json')} |
 ForEach-Object {$sources[$_.FullName.Substring($projectDirectory.Length+1)]=(Get-FileHash -LiteralPath $_.FullName).Hash}
}
foreach($relative in @('tests/integration/unified_edit_gpu_probe.gd','scripts/simulation/sand_water_domain.gd','scripts/simulation/edit_validation/edit_protocol.gd','assets/brushes/molded_material_candidate.json','assets/brushes/castle/four_towers_v1.rgba32f','shaders/simulation/shallow_edge_flux.glsl','shaders/simulation/shallow_drain_scale.glsl','shaders/simulation/shallow_update_state.glsl','shaders/simulation/erosion/sediment_step.glsl','shaders/simulation/material/material_step.glsl','shaders/simulation/edit_validation/staged_slope.glsl','shaders/simulation/brushes/molded_slope.glsl','shaders/simulation/edit_validation/staged_slope_consume.glsl','shaders/simulation/material/material_commit.glsl','shaders/simulation/brushes/mold_support_step.glsl','shaders/simulation/edit_validation/water_displace_compensated.glsl','shaders/simulation/edit_validation/water_packed_cached.glsl','shaders/simulation/edit_validation/water_velocity_prefetch.glsl','tests/integration/unified_edit_suspended_probe.gd','tests/integration/unified_edit_legacy_coupled_reference.gd','tests/integration/unified_edit_legacy_response_reference.gd','shaders/simulation/edit_validation/water_velocity_apply.glsl','shaders/simulation/brushes/water_velocity.glsl','scripts/simulation/gpu_shallow_solver.gd','scripts/simulation/erosion/gpu_sediment_coupler.gd','scripts/simulation/material/gpu_material_coupler.gd','scripts/simulation/edit_validation/staged_slope_coupler.gd','shaders/simulation/erosion/copy_after_boundary.glsl')){
 $sources[$relative]=(Get-FileHash -LiteralPath (Join-Path $projectDirectory $relative)).Hash
}
foreach($relative in @($ProbeScript.Substring(6),'tests/integration/unified_edit_observed_executor.gd','tests/integration/unified_edit_target_probe.gd','tests/fixtures/unified_edit/wall_small_buffer.tres')){
 $sources[$relative]=(Get-FileHash -LiteralPath (Join-Path $projectDirectory $relative)).Hash
}
foreach($relative in @('scripts/collision/collision_prepare_job.gd','scripts/simulation/unified_edit/height_surface.gd','scenes/unified_edit_height_surface.tscn','scenes/unified_edit_runtime.tscn','tests/integration/unified_edit_timed_pipeline.gd','tests/integration/unified_edit_height_probe.gd','tests/fixtures/unified_edit/view_consumer.tscn','tests/fixtures/unified_edit/view_consumer.gdshader','tests/integration/unified_edit_failed_views.gd','tests/integration/unified_edit_restore_probe.gd','tests/integration/unified_edit_legacy_visual_reference.gd','scripts/simulation/edit_validation/checkpoint_foam_field.gd','scripts/visual/gpu_foam_field.gd','scripts/visual/gpu_gravel_field.gd','tests/visual_water_alignment/prototypes/reference_local_front_field.gd','tests/visual_water_alignment/prototypes/reference_local_front_x.glsl','tests/visual_water_alignment/prototypes/reference_local_front_x_wide.glsl','tests/visual_water_alignment/prototypes/reference_local_front_z.glsl','shaders/simulation/visual_foam_step.glsl','shaders/simulation/visual_gravel_step.glsl','tests/fixtures/unified_edit/visual_consumer.tscn','tests/fixtures/unified_edit/visual_consumer.gdshader','tests/integration/unified_edit_observed_boundary.gd','scripts/scenarios/test1_geometry_layout.gd','scripts/scenarios/test1_playable_layout.gd','assets/test1_geometry/initial_state.f32','assets/test1_geometry/water_cycle.json','assets/test1_water_motion/capture_state.rgba32f','tests/integration/unified_edit_boundary_math_trace.gd','tests/fixtures/unified_edit/boundary_math_trace.glsl')){$sources[$relative]=(Get-FileHash -LiteralPath (Join-Path $projectDirectory $relative)).Hash}
$started=Get-Date
$runs=@()
foreach($probeCase in $Cases){
 if($probeCase -notin @('normal','water_1','water_2','water_3','water_64','water_100','upload','readback','truncate','identity','unknown_state','fatal','counter','tick_counter','revision_counter','bad_cfl','controls','castle','wall','stroke_bounds','smooth','compact','local_mixed','local_invalid','transfer','transfer_reverse','transfer_capacity','transfer_limited','transfer_stress','transfer_empty','transfer_invalid','suspended','suspended_sweep','suspended_disabled','suspended_invalid','coupled_1','coupled_2','coupled_3','coupled_64','coupled_1_molded','coupled_3_molded','water_fill_1','water_fill_2','water_fill_3','water_dig_1','water_wall_3','water_shovel_3','water_castle_3','water_split_1','water_partial_1','all_profiles','all_profiles_batch','water_fail_3','water_cfl_1','water_capacity_1','water_sealed_1','water_dry_3','water_many_1','water_limited_3','water_only_3','water_plain_3','water_moldplain_3','water_materialbad_3','water_refbad_3','water_nan_3','water_overflow_3','height_basic','height_faults','height_erosion','height_flow','height_batch','height_coverage','height_long','views_core','views_fatal','half_native','init_transport','init_state','init_executor','init_water','init_coupled','init_height','init_views','init_bad_field','init_bad_domain','init_null_domain','init_compile','init_unknown','restore_native','restore_distinct','restore_hold','restore_registration','restore_corrupt','restore_unknown','restore_cancel','restore_cohesion','early_cancel','early_release','early_release_unconfigured','checkpoint_queued','checkpoint_recorded','checkpoint_completed','checkpoint_physics','checkpoint_capacity','checkpoint_held','checkpoint_registration','checkpoint_unknown','checkpoint_truncate','checkpoint_corrupt','checkpoint_cancel','checkpoint_cancel_read','checkpoint_close','checkpoint_existing','checkpoint_identity','checkpoint_upload','checkpoint_readback','checkpoint_receiver','checkpoint_quantized','handoff_native','handoff_preview','handoff_detach','handoff_preflight','handoff_initialize','handoff_cancel','handoff_repeat','handoff_capacity','handoff_unknown','handoff_upload','handoff_visuals','handoff_boundary','visual_all','visual_foam','visual_gravel','visual_front','visual_wide','visual_indices','visual_edit','visual_fatal','visual_bad_cfl','visual_init_failure','visual_init_unknown','visual_capture_unknown','visual_restore_failure','boundary_main','boundary_capture','boundary_backwash','boundary_geometry','boundary_queued','boundary_capacity','boundary_upload','boundary_geometry_rise','boundary_geometry_fall')){throw 'Unknown probe case'}
 $caseDirectory=Join-Path $OutputDirectory $probeCase
 New-Item -ItemType Directory -Path $caseDirectory | Out-Null
 $resultPath=Join-Path $caseDirectory 'probe.json'
 $logPath=Join-Path $caseDirectory 'probe.log'
 $engineArguments=@('--path',$projectDirectory,'--script',$ProbeScript,'--quit-after','3600','--log-file',$logPath,'--',('--output='+$resultPath),('--case='+$probeCase))
 & $Engine @engineArguments 2>&1 | Out-File -LiteralPath (Join-Path $caseDirectory 'stdout.txt') -Encoding utf8
 $exitCode=$LASTEXITCODE
 $result=if(Test-Path -LiteralPath $resultPath){Get-Content -LiteralPath $resultPath -Raw | ConvertFrom-Json}else{$null}
 $log=if(Test-Path -LiteralPath $logPath){Get-Content -LiteralPath $logPath -Raw}else{''}
 $log+=[Environment]::NewLine+(Get-Content -LiteralPath (Join-Path $caseDirectory 'stdout.txt') -Raw)
 $passed=$exitCode -eq 0 -and $null -ne $result -and $result.pass -and -not $log.Contains('SCRIPT ERROR:') -and -not $log.Contains("`nERROR:") -and $log -notmatch 'RID[s]? of type .* (was|were) leaked'
 $runs+=@{case=$probeCase;arguments=$engineArguments;exit_code=$exitCode;pass=$passed;checks=if($result){$result.checks.Count}else{0};result=$resultPath;result_sha256=if($result){(Get-FileHash -LiteralPath $resultPath).Hash}else{''}}
 Write-Output ('GPU_CONTRACT '+$probeCase+' '+$passed)
 if(-not $passed){break}
}
$drift=@($sources.Keys | Where-Object {(Get-FileHash -LiteralPath (Join-Path $projectDirectory $_)).Hash -ne $sources[$_]})
$passed=$runs.Count -eq $Cases.Count -and @($runs | Where-Object {-not $_.pass}).Count -eq 0 -and $drift.Count -eq 0
$runRole=if($ProbeScript -like '*boundary_probe.gd'){'T06 prescribed tide/wave and geometry boundary capture/restore component; no formal entry/cost claim'}elseif($ProbeScript -like '*visuals_probe.gd'){'T06 enabled visual history common-stage and checkpoint component; no formal entry/boundary/cost claim'}elseif($ProbeScript -like '*handoff_probe.gd'){'T06 two-slot consumer handoff component; disabled effects; no formal entry/cost claim'}elseif($ProbeScript -like '*checkpoint_probe.gd'){'T06 common production checkpoint capture/save/settlement and native continuation; no formal handoff claim'}elseif($ProbeScript -like '*early_lifecycle_probe.gd'){'T06 pre-initialization close/release and terminal reuse guards'}elseif($ProbeScript -like '*restore_probe.gd'){'T06 native candidate restore/verification and active-domain preservation; no formal atomic swap claim'}elseif($ProbeScript -like '*initialization_probe.gd'){'T06 candidate initialization failure/unknown cleanup; no formal lifecycle claim'}elseif($ProbeScript -like '*half_gpu_probe.gd'){'T06 native unit half upload and read-only publication; no full restore claim'}elseif($ProbeScript -like '*views_probe.gd'){'T05 read-only complete-view/preview/material ownership probes; no cost claim'}elseif($ProbeScript -like '*height_probe.gd'){'T05 complete height/dirty/consumer/bounded batch probes; no cost claim'}elseif($ProbeScript -like '*water_probe.gd'){'T03/G4 shared material/water candidates; no cost claim'}elseif($ProbeScript -like '*target_probe.gd'){'T03 common candidates and precommit proof; no cost claim'}else{'T02 ordinary edit/water/fault regression; no cost claim'}
@{role=$runRole;engine=$Engine;engine_sha256=(Get-FileHash -LiteralPath $Engine).Hash;tool_sha256=(Get-FileHash -LiteralPath $PSCommandPath).Hash;started=$started.ToString('o');elapsed_ms=((Get-Date)-$started).TotalMilliseconds;pass=$passed;drift=$drift;sources=$sources;runs=$runs} | ConvertTo-Json -Depth 14 | Set-Content -LiteralPath (Join-Path $OutputDirectory 'run-manifest.json') -Encoding utf8
if(-not $passed){exit 1}
